package matteroverdrive.client.screen;
import matteroverdrive.blockentity.StarMapBlockEntity;import matteroverdrive.menu.StarMapMenu;import matteroverdrive.network.ModNetwork;import matteroverdrive.starmap.StarMapCatalog;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;import java.util.Locale;
public class StarMapScreen extends AbstractContainerScreen<StarMapMenu>{private enum View{GALAXY,QUADRANT,STAR,PLANET}private static final int MAP_X=10,MAP_Y=25,MAP_W=260,MAP_H=64,TRAVEL_X=200,TRAVEL_Y=103,TRAVEL_W=68,TRAVEL_H=25,ECO_X=112,ECO2_X=154,ECO_W=40,ECO_H=10;private View view=View.GALAXY;private StarMapCatalog.Quadrant quadrant;private StarMapCatalog.Star star;private StarMapCatalog.Planet planet;private float zoom=1,panX,panY;private double dragX,dragY;private boolean dragging;public StarMapScreen(StarMapMenu m,Inventory i,Component t){super(m,i,t);imageWidth=280;imageHeight=248;inventoryLabelY=137;}@Override public void render(GuiGraphics g,int x,int y,float p){renderBackground(g);super.render(g,x,y,p);renderTooltip(g,x,y);}@Override protected void renderBg(GuiGraphics g,float p,int mx,int my){MachineScreenStyle.drawFrame(g,leftPos,topPos,imageWidth,imageHeight,inventoryLabelY,MachineScreenStyle.CYAN);int x=leftPos+MAP_X,y=topPos+MAP_Y;g.fill(x,y,x+MAP_W,y+MAP_H,0xEE081117);g.renderOutline(x,y,MAP_W,MAP_H,MachineScreenStyle.CYAN);int cx=x+MAP_W/2+Math.round(panX),cy=y+MAP_H/2+Math.round(panY);switch(view){case GALAXY->renderGalaxy(g,x,y,cx,cy);case QUADRANT->renderQuadrant(g,x,y,cx,cy);case STAR,PLANET->renderStarSystem(g,x,y,cx,cy);}}private void renderGalaxy(GuiGraphics g,int x,int y,int cx,int cy){for(var q:StarMapCatalog.quadrants())dot(g,x,y,cx+Math.round(q.x()*zoom),cy+Math.round(q.y()*zoom),4,0xFFFFD56A);}private void renderQuadrant(GuiGraphics g,int x,int y,int cx,int cy){if(quadrant==null)return;for(var e:quadrant.stars())dot(g,x,y,cx+Math.round(e.x()*zoom),cy+Math.round(e.y()*zoom),3,0xFF73E8FF);}private void renderStarSystem(GuiGraphics g,int x,int y,int cx,int cy){if(star==null)return;int n=star.planets().size();for(int i=0;i<n;i++){double a=Math.PI*2*i/Math.max(1,n);int rx=Math.round((13+i*8)*zoom),ry=Math.round((8+i*5)*zoom);var e=star.planets().get(i);dot(g,x,y,cx+(int)Math.round(Math.cos(a)*rx),cy+(int)Math.round(Math.sin(a)*ry),e==planet?4:3,e==planet?0xFF78FF9B:0xFFC7DCE3);}dot(g,x,y,cx,cy,5,0xFFFFD56A);}private static void dot(GuiGraphics g,int x,int y,int sx,int sy,int size,int color){if(sx>x+2&&sx<x+MAP_W-2&&sy>y+2&&sy<y+MAP_H-2)g.fill(sx-size/2,sy-size/2,sx-size/2+size,sy-size/2+size,color);}@Override protected void renderLabels(GuiGraphics g,int mx,int my){g.drawString(font,title,8,9,MachineScreenStyle.TEXT,false);g.drawString(font,"Fleet H"+menu.fleetHull()+" S"+menu.fleetShield()+" F"+menu.fleetFirepower()+" V"+menu.fleetVictories(),153,9,menu.fleetCombat()?MachineScreenStyle.AMBER:MachineScreenStyle.MUTED,false);g.drawString(font,breadcrumb(),12,94,MachineScreenStyle.CYAN,false);g.drawString(font,"Contracts "+menu.active()+" / ready "+menu.complete(),171,94,MachineScreenStyle.MUTED,false);if(view==View.PLANET&&planet!=null)renderPlanetStats(g);else{g.drawString(font,guidance(),12,104,MachineScreenStyle.TEXT,false);g.drawString(font,String.format(Locale.ROOT,"%.1fx | wheel/drag | RMB back",zoom),154,104,MachineScreenStyle.MUTED,false);}g.drawString(font,playerInventoryTitle,8,inventoryLabelY,MachineScreenStyle.MUTED,false);}private void renderPlanetStats(GuiGraphics g){g.drawString(font,planet.type()+" | Orbit "+planet.orbit(),12,104,MachineScreenStyle.TEXT,false);if(current()&&menu.currentOwnerState()!=0){g.drawString(font,"E "+signed(menu.currentEnergyProduction())+" M "+signed(menu.currentMatterProduction())+" P "+menu.currentPopulation(),12,114,prodColor(),false);g.drawString(font,"H "+String.format(Locale.ROOT,"%.2f",menu.currentHappinessHundredths()/100.0)+" B "+menu.currentBuildingCount()+"/"+menu.currentBuildingCapacity(),12,124,MachineScreenStyle.CYAN,false);renderEconomy(g);}else{g.drawString(font,"Hab "+planet.habitability()+"% Temp "+planet.temperature()+"K",12,114,planet.habitability()>=60?MachineScreenStyle.GREEN:MachineScreenStyle.MUTED,false);g.drawString(font,"G "+planet.gravityPercent()+"% M"+planet.moons()+" "+(planet.atmosphere()?"ATMO":"VAC"),12,124,MachineScreenStyle.CYAN,false);if(current())renderEconomy(g);}int color=menu.fleetCombat()?MachineScreenStyle.AMBER:menu.traveling()&&!menu.encounterResolved()?MachineScreenStyle.AMBER:canTravel()?MachineScreenStyle.CYAN:MachineScreenStyle.MUTED;g.fill(TRAVEL_X,TRAVEL_Y,TRAVEL_X+TRAVEL_W,TRAVEL_Y+TRAVEL_H,0xCC0C171D);g.renderOutline(TRAVEL_X,TRAVEL_Y,TRAVEL_W,TRAVEL_H,color);String top,bottom;if(menu.fleetCombat()){top=menu.fleetAttackCooldown()>0?"RECHARGE":"FIRE";bottom="ENEMY "+menu.enemyHull()+"/"+menu.enemyMaxHull();}else if(menu.traveling()){top="EN ROUTE";bottom=!menu.encounterResolved()&&menu.encounterRemaining()>0?"EVENT "+Math.max(1,(menu.encounterRemaining()+19)/20)+"s":Math.max(1,(menu.travelRemaining()+19)/20)+"s";}else if(current()){top="CURRENT";bottom="LOCATION";}else{top="TRAVEL";int q=StarMapCatalog.quadrantIndex(quadrant),s=StarMapCatalog.starIndex(quadrant,star),p=StarMapCatalog.planetIndex(star,planet),ticks=StarMapCatalog.travelTicks(menu.currentQuadrant(),menu.currentStar(),menu.currentPlanet(),q,s,p);bottom=Math.max(1,(ticks+19)/20)+"s";}g.drawCenteredString(font,top,TRAVEL_X+TRAVEL_W/2,TRAVEL_Y+4,color);g.drawCenteredString(font,bottom,TRAVEL_X+TRAVEL_W/2,TRAVEL_Y+14,MachineScreenStyle.MUTED);}private int prodColor(){return menu.currentEnergyProduction()>=0&&menu.currentMatterProduction()>=0?MachineScreenStyle.GREEN:MachineScreenStyle.AMBER;}private static String signed(int v){return v>=0?"+"+v:Integer.toString(v);}private void renderEconomy(GuiGraphics g){if(menu.buildAction()!=StarMapBlockEntity.ECON_NONE){wideEco(g,104,"BUILD "+buildName(menu.buildAction())+" "+Math.max(1,(menu.buildRemaining()+19)/20)+"s",MachineScreenStyle.AMBER);wideEco(g,115,"S"+menu.scoutShips()+" C"+menu.colonizerShips()+" / "+menu.currentFleetCapacity(),MachineScreenStyle.MUTED);wideEco(g,126,"EX"+menu.currentExtractors()+" GN"+menu.currentGenerators()+" RS"+menu.currentResidential(),MachineScreenStyle.MUTED);return;}eco(g,ECO_X,104,"S "+menu.scoutShips(),menu.currentHasFactory()?MachineScreenStyle.CYAN:MachineScreenStyle.MUTED);eco(g,ECO_X,115,"C "+menu.colonizerShips(),menu.currentHasFactory()?MachineScreenStyle.CYAN:MachineScreenStyle.MUTED);String third;int color;if(menu.currentOwnerState()==0){third="CLAIM";color=menu.colonizerShips()>0?MachineScreenStyle.GREEN:MachineScreenStyle.MUTED;}else if(menu.currentOwnerState()==2){third="FOREIGN";color=MachineScreenStyle.MUTED;}else if(!menu.currentHasFactory()){third="FACTORY";color=MachineScreenStyle.CYAN;}else{third="H "+menu.currentHangars();color=MachineScreenStyle.CYAN;}eco(g,ECO_X,126,third,color);int own=menu.currentOwnerState()==1?MachineScreenStyle.CYAN:MachineScreenStyle.MUTED;eco(g,ECO2_X,104,"EX "+menu.currentExtractors(),own);eco(g,ECO2_X,115,"GN "+menu.currentGenerators(),own);eco(g,ECO2_X,126,"RS "+menu.currentResidential(),own);}private void eco(GuiGraphics g,int x,int y,String text,int color){g.fill(x,y,x+ECO_W,y+ECO_H,0xCC0C171D);g.renderOutline(x,y,ECO_W,ECO_H,color);g.drawCenteredString(font,text,x+ECO_W/2,y+1,color);}private void wideEco(GuiGraphics g,int y,String text,int color){g.fill(ECO_X,y,ECO2_X+ECO_W,y+ECO_H,0xCC0C171D);g.renderOutline(ECO_X,y,ECO2_X+ECO_W-ECO_X,ECO_H,color);g.drawCenteredString(font,text,(ECO_X+ECO2_X+ECO_W)/2,y+1,color);}private static String buildName(int a){return switch(a){case StarMapBlockEntity.ECON_SCOUT->"SCOUT";case StarMapBlockEntity.ECON_COLONIZER->"COLONIZER";case StarMapBlockEntity.ECON_FACTORY->"FACTORY";case StarMapBlockEntity.ECON_HANGAR->"HANGAR";case StarMapBlockEntity.ECON_EXTRACTOR->"EXTRACTOR";case StarMapBlockEntity.ECON_GENERATOR->"GENERATOR";case StarMapBlockEntity.ECON_RESIDENTIAL->"RESIDENTIAL";default->"?";};}private boolean current(){return StarMapCatalog.quadrantIndex(quadrant)==menu.currentQuadrant()&&StarMapCatalog.starIndex(quadrant,star)==menu.currentStar()&&StarMapCatalog.planetIndex(star,planet)==menu.currentPlanet();}private boolean canTravel(){return planet!=null&&!menu.traveling()&&!menu.fleetCombat()&&!current();}private String breadcrumb(){return switch(view){case GALAXY->"Galaxy";case QUADRANT->"Galaxy > "+quadrant.name();case STAR->"Galaxy > "+quadrant.name()+" > "+star.name();case PLANET->"Galaxy > "+quadrant.name()+" > "+star.name()+" > "+planet.name();};}private String guidance(){return switch(view){case GALAXY->"Click quadrant";case QUADRANT->"Click star";case STAR->"Click planet | "+star.planets().size()+" planets | "+star.temperature()+" K star";case PLANET->"Planet selected";};}@Override public boolean mouseScrolled(double x,double y,double d){zoom=Math.max(.45F,Math.min(2.5F,zoom+(float)d*.15F));return true;}@Override public boolean mouseClicked(double mx,double my,int b){if(b==0&&view==View.PLANET&&planet!=null&&current()&&menu.buildAction()==StarMapBlockEntity.ECON_NONE){int lx=(int)(mx-leftPos),ly=(int)(my-topPos);if(ly>=104&&ly<136){int action=StarMapBlockEntity.ECON_NONE;if(lx>=ECO_X&&lx<ECO_X+ECO_W){if(ly<114)action=StarMapBlockEntity.ECON_SCOUT;else if(ly<125)action=StarMapBlockEntity.ECON_COLONIZER;else action=menu.currentOwnerState()==0?StarMapBlockEntity.ECON_COLONIZE:menu.currentOwnerState()==1&&!menu.currentHasFactory()?StarMapBlockEntity.ECON_FACTORY:menu.currentOwnerState()==1?StarMapBlockEntity.ECON_HANGAR:StarMapBlockEntity.ECON_NONE;}else if(lx>=ECO2_X&&lx<ECO2_X+ECO_W&&menu.currentOwnerState()==1){if(ly<114)action=StarMapBlockEntity.ECON_EXTRACTOR;else if(ly<125)action=StarMapBlockEntity.ECON_GENERATOR;else action=StarMapBlockEntity.ECON_RESIDENTIAL;}if(action!=StarMapBlockEntity.ECON_NONE){ModNetwork.requestStarMapEconomy(menu.mapPos(),action);return true;}}}if(b==0&&view==View.PLANET&&planet!=null&&mx>=leftPos+TRAVEL_X&&mx<leftPos+TRAVEL_X+TRAVEL_W&&my>=topPos+TRAVEL_Y&&my<topPos+TRAVEL_Y+TRAVEL_H){if(menu.fleetCombat()&&menu.fleetAttackCooldown()==0)ModNetwork.requestStarMapFleetAttack(menu.mapPos());else if(canTravel())ModNetwork.requestStarMapTravel(menu.mapPos(),StarMapCatalog.quadrantIndex(quadrant),StarMapCatalog.starIndex(quadrant,star),StarMapCatalog.planetIndex(star,planet));return true;}int x=leftPos+MAP_X,y=topPos+MAP_Y;if(mx<x||mx>=x+MAP_W||my<y||my>=y+MAP_H)return super.mouseClicked(mx,my,b);if(b==1){back();return true;}if(b==0){if(select(mx,my,x,y))return true;dragging=true;dragX=mx;dragY=my;return true;}return super.mouseClicked(mx,my,b);}private void back(){switch(view){case PLANET->{view=View.STAR;planet=null;}case STAR->{view=View.QUADRANT;star=null;planet=null;}case QUADRANT->{view=View.GALAXY;quadrant=null;}case GALAXY->{}}reset();}private boolean select(double mx,double my,int x,int y){int cx=x+MAP_W/2+Math.round(panX),cy=y+MAP_H/2+Math.round(panY);if(view==View.GALAXY){for(var q:StarMapCatalog.quadrants())if(near(mx,my,cx+q.x()*zoom,cy+q.y()*zoom)){quadrant=q;view=View.QUADRANT;reset();return true;}}else if(view==View.QUADRANT&&quadrant!=null){for(var e:quadrant.stars())if(near(mx,my,cx+e.x()*zoom,cy+e.y()*zoom)){star=e;view=View.STAR;reset();return true;}}else if((view==View.STAR||view==View.PLANET)&&star!=null){int n=star.planets().size();for(int i=0;i<n;i++){double a=Math.PI*2*i/Math.max(1,n),sx=cx+Math.cos(a)*(13+i*8)*zoom,sy=cy+Math.sin(a)*(8+i*5)*zoom;if(near(mx,my,sx,sy)){planet=star.planets().get(i);view=View.PLANET;return true;}}}return false;}private static boolean near(double x,double y,double sx,double sy){return Math.abs(x-sx)<=6&&Math.abs(y-sy)<=6;}private void reset(){panX=panY=0;zoom=1;}@Override public boolean mouseDragged(double mx,double my,int b,double ax,double ay){if(dragging&&b==0){panX=Math.max(-105,Math.min(105,panX+(float)(mx-dragX)));panY=Math.max(-48,Math.min(48,panY+(float)(my-dragY)));dragX=mx;dragY=my;return true;}return super.mouseDragged(mx,my,b,ax,ay);}@Override public boolean mouseReleased(double x,double y,int b){if(b==0)dragging=false;return super.mouseReleased(x,y,b);}}
